import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Propriété","description":"","frontmatter":{},"headers":[],"relativePath":"fr/repair-station-business/ownership.md","filePath":"fr/repair-station-business/ownership.md"}'),s={name:"fr/repair-station-business/ownership.md"};function i(o,e,u,p,l,d){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="propriete" tabindex="-1">Propriété <a class="header-anchor" href="#propriete" aria-label="Permalink to &quot;Propriété&quot;">​</a></h1><h2 id="mettre-une-station-en-vente" tabindex="-1">Mettre une station en vente <a class="header-anchor" href="#mettre-une-station-en-vente" aria-label="Permalink to &quot;Mettre une station en vente&quot;">​</a></h2><p>Seules les stations en vente peuvent être achetées. En tant qu&#39;admin avec <code>nay_repair_business.config</code> :</p><ol><li>Créez vos stations avec l&#39;<a href="/fr/repair-station/stations">éditeur de la Repair Station</a>.</li><li>Ouvrez le panneau d&#39;administration avec <code>/nay:repairbusiness</code>, ou par l&#39;action <strong>Gérer les stations à vendre</strong> de <code>/nay</code>.</li><li>Choisissez une station, saisissez un prix de vente et appuyez sur <strong>Mettre en vente</strong>.</li></ol><p>La même liste se trouve dans <code>/nay</code> sous <strong>Stations à vendre</strong>. Une station en vente affiche un blip sur la carte et une invite avec son prix. Tant que personne ne la possède, <strong>Stations à vendre sans propriétaire</strong> décide si elle reste ouverte (les joueurs y réparent comme d&#39;habitude) ou ferme jusqu&#39;à ce que quelqu&#39;un l&#39;achète. Une station désactivée dans la Repair Station ne peut pas être achetée et n&#39;a pas de blip.</p><h2 id="acheter" tabindex="-1">Acheter <a class="header-anchor" href="#acheter" aria-label="Permalink to &quot;Acheter&quot;">​</a></h2><p>Le joueur va à la station et appuie sur <strong>E</strong>. Une confirmation indique le prix et le compte débité (<strong>Compte d&#39;achat</strong>). Un joueur peut posséder jusqu&#39;à <strong>Stations par joueur</strong> stations. L&#39;achat est vérifié par le serveur, à 8 mètres de la station au plus, et remboursé si quelque chose échoue.</p><h2 id="la-tablette" tabindex="-1">La tablette <a class="header-anchor" href="#la-tablette" aria-label="Permalink to &quot;La tablette&quot;">​</a></h2><p>Le propriétaire appuie sur <strong>E</strong> à la station pour ouvrir la tablette, à 8 mètres ou moins :</p><ul><li><strong>Aperçu</strong> : stock, caisse, réparations du jour et des 7 derniers jours, dernières opérations.</li><li><strong>Stock</strong> : acheter des pièces ou remettre des objets, voir <a href="/fr/repair-station-business/stock">Stock</a>.</li><li><strong>Caisse</strong> : retirer de l&#39;argent en espèces ou en banque, ou verser de l&#39;argent de la banque dans la caisse.</li><li><strong>Réglages</strong> : pourcentage des prix, nom de la station, vente de la station.</li></ul><p>Le nom choisi par le propriétaire remplace le nom de la station dans le menu de réparation. Le pourcentage modifie le prix de chaque prestation : les joueurs voient le prix final avant de payer, et la taxe (<strong>Taxe</strong>) est prélevée sur chaque paiement, la caisse reçoit le reste.</p><h2 id="vendre-et-perdre-une-station" tabindex="-1">Vendre et perdre une station <a class="header-anchor" href="#vendre-et-perdre-une-station" aria-label="Permalink to &quot;Vendre et perdre une station&quot;">​</a></h2><ul><li><strong>Vente</strong> : le propriétaire reçoit <strong>Rachat</strong> pour cent du prix d&#39;achat, plus la caisse, sur son compte bancaire. La station est de nouveau en vente à son prix, sauf si le staff l&#39;a retirée de la vente.</li><li><strong>Expulsion</strong> : le staff peut expulser un propriétaire depuis le panneau d&#39;administration. Il est payé comme pour une vente.</li><li><strong>Inactivité</strong> : un propriétaire qui n&#39;ouvre pas la tablette pendant <strong>Limite d&#39;inactivité</strong> jours perd la station et est payé comme pour une vente. 0 le désactive.</li><li><strong>Station supprimée</strong> : quand une station est supprimée dans l&#39;éditeur de la Repair Station, son propriétaire est payé comme pour une vente et la station sort du système.</li></ul><p>Un propriétaire hors ligne à ce moment reçoit l&#39;argent, une seule fois, au prochain chargement du personnage, avec une notification. Chaque opération est enregistrée dans le registre, lisible avec l&#39;<a href="/fr/repair-station-business/api">API</a>.</p>',14)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
